    {
      "schema_version": 1,
      "investigation_id": "ra.ct-pulmonary-nodules",
      "module_id": "rad.4.pulmonary-nodule",
      "title": "Pulmonary nodules: whole reporting and13-question conditional structure draft",
      "source_contract_definition": "Exact current effective reporting/report_templates/walkthrough/reading snapshot at base main; proposals are separate and do not overwrite historical contract.",
      "source_contract_sha256": "9036f92240e71b853565954f01ba24df2c3a9df110faa5e9c0f6b5168ae8ec6c",
      "shared_curriculum_quiz_sha256": "391c4f9b3215680d61b05d68ec591f1e921e57790f24d0536cfe74a256abfa27",
      "scope_status": "conditional_whole_module_draft_requires_thoracic_radiologist_review_and_actual_site_instantiation",
      "required_representations": [
        "image",
        "schematic",
        "model"
      ],
      "modality_scope": [
        "CT",
        "PET-CT"
      ],
      "reporting_checklist": [
        {
          "label": "Eligibility",
          "detail": "Record actual indication, age, immune status, cancer history, screening context, relevant risk/comorbidity and guideline exclusions before a follow-up decision."
        },
        {
          "label": "Nodule type",
          "detail": "Inventory every actual nodule by ID, side/lobe/segment where supported, source series/image and solid/pure-ground-glass/part-solid appearance; retain unassessed localization or morphology."
        },
        {
          "label": "Morphology",
          "detail": "Describe actual whole-nodule and dense-component boundaries, margins, verified fat/calcium pattern and pleural/fissural/airway/vascular interfaces. CT appearance and reader ratings are not histology."
        },
        {
          "label": "Measurement",
          "detail": "Record actual same-plane long/short axes, rounded mean diameter and separate dense-component dimensions; use consistent validated volumetry and software where appropriate. Distinguish point HU from a verified small intranodular ROI."
        },
        {
          "label": "Growth",
          "detail": "Review genuine original comparison studies, technical compatibility and actual interval; identify each new or changing component and the most suspicious nodule without inventing a prior from a source example."
        }
      ],
      "reporting_template_sections": [
        {
          "heading": "PATHWAY",
          "body": "Actual context: [incidental / screening / oncology / infection or other]. Age, immune status, cancer history, symptoms, risk/comorbidity and preferences: [ ]. Guideline eligibility/exclusions and selected pathway/version: [ ]."
        },
        {
          "heading": "NODULE INVENTORY",
          "body": "Every actual nodule ID: [ ]. Side/lobe/segment and localization limits: [ ]. Source series/image: [ ]. Appearance: [solid / pure ground glass / part-solid / uncertain]; unresolved extent or limits: [ ]."
        },
        {
          "heading": "SIZE AND MORPHOLOGY",
          "body": "Actual largest-dimension source plane: [ ]. Long/short axes: [ ]/[ ] mm; rounded mean: [ ] mm. Total/each dense-component size: [ ]. Validated volume/software/version if used: [ ]. Margins and actual pleural/fissural/airway/vascular relations: [ ]. Verified ROI fat/calcium distribution and method/limits: [ ]."
        },
        {
          "heading": "INTERVAL CHANGE",
          "body": "Genuine prior date and source examination: [ ]. Remeasured previous/current total/dense-component size or volume: [ ]. Method, software/version, thickness/kernel and other comparability: [ ]. Change: [none demonstrated / present / uncertain / not assessable]; elapsed interval and limits: [ ]."
        },
        {
          "heading": "ASSESSMENT",
          "body": "Most suspicious actual nodule and reason: [ ]. Benign-pattern evidence and uncertainty: [ ]. Applicable single/multiple and solid/subsolid guideline/version/category: [ ]. Individualized recommendation, timeframe, rationale and communication if needed: [ ]."
        }
      ],
