  "ra.ct-pulmonary-nodules": {
    "reporting": {
      "protocol": [
        "Use the complete acquired thorax with contiguous thin reconstructed sections at most 1.5 mm, typically 1 mm, and explicit coverage/quality limitations. Record nominal reconstructed section thickness separately from reconstruction centre spacing and pixel spacing. Record acquisition collimation only when independently documented; do not infer it from DICOM SliceThickness.",
        "Use suitable lung windows and actual multiplanar reconstructions to distinguish nodule/linear scar and solid/subsolid components; retain the actual source reconstructions and kernel.",
        "Measure verified fat or calcium on the thinnest available nonsharpened series with a small ROI, excluding air/edge partial-volume contamination. A single point value is insufficient.",
        "Compare all available original prior studies, including early baseline; document dates, reconstruction/software compatibility and uncertainty. A current source example is not an invented prior examination.",
        "Declare incidental/screening/oncology/infectious context, eligibility and exclusions before applying a named current guideline. Distinguish single/multiple and solid/pure-ground-glass/part-solid pathways.",
        "Document each nodule ID/site/series/image, total/solid-component measurement, margins, verified fat/calcification, relevant pleural/airway/vascular relationships and actual interval change. Reader scores are not histological diagnoses."
      ],
      "checklist": [
        {
          "label": "Eligibility",
          "detail": "Record actual indication, age, immune status, cancer history, screening context, relevant risk/comorbidity and guideline exclusions before a follow-up decision."
        },
        {
          "label": "Nodule type",
          "detail": "Inventory every actual nodule by ID, side/lobe/segment where supported, source series/image and solid/pure-ground-glass/part-solid appearance; retain unassessed localization or morphology."
        },
        {
          "label": "Morphology",
          "detail": "Describe actual whole-nodule and dense-component boundaries, margins, verified fat/calcium pattern and pleural/fissural/airway/vascular interfaces. CT appearance and reader ratings are not histology."
        },
        {
          "label": "Measurement",
          "detail": "Record actual same-plane long/short axes, rounded mean diameter and separate dense-component dimensions; use consistent validated volumetry and software where appropriate. Distinguish point HU from a verified small intranodular ROI."
        },
        {
          "label": "Growth",
          "detail": "Review genuine original comparison studies, technical compatibility and actual interval; identify each new or changing component and the most suspicious nodule without inventing a prior from a source example."
        }
      ],
      "measurements": [
        {
          "name": "Mean diameter",
          "method": "On thin reconstructed images use the plane showing largest dimensions, average long and perpendicular short axes on the same image and record the nearest whole mm. Record actual source plane and uncertainty.",
          "pitfall": "Source SR maximal axial outside-contour diameter is not the Fleischner mean-caliper measurement; thick or incompatible reconstructions and partial volume can alter apparent morphology/size."
        },
        {
          "name": "Solid component",
          "method": "Measure each actual dense component separately on comparable thin-section lung-window images; record total size, component size, source plane and technical limitations.",
          "pitfall": "Whole-nodule stability does not negate dense-component growth; CT density is not proof of histological invasion."
        },
        {
          "name": "Intranodular attenuation ROI",
          "method": "When measuring suspected fat or calcium, use the thinnest available nonsharpened source CT series and a small ROI within the actual nodule, excluding adjacent air, edges and artefact; record mean/range, source calibration and limitations.",
          "pitfall": "A native point HU readout or edge-contaminated negative value does not establish intranodular macroscopic fat, a hamartoma or a clinical diagnosis."
        },
        {
          "name": "Interval size or volume change",
          "method": "Reopen actual prior images, remeasure comparable anatomy and record dates, elapsed time, reconstruction/kernel compatibility and method/software version. State uncertainty where growth cannot be established.",
          "pitfall": "This LIDC source supplies one examination; deidentified dates, reader disagreements and separate masks are not longitudinal growth or patient registration."
        }
      ],
      "classification": {
        "name": "Incidental pulmonary nodule framework",
        "version": "Fleischner Society 2017",
        "applicability": "Adults ≥35 with incidental nodules, excluding screening, immunocompromise and known cancer.",
        "summary": "Use the applicable single/multiple and solid/pure-ground-glass/part-solid pathway and actual risk/context. Screening uses its current programme system; known malignancy/immunocompromise and other exclusions require the actual clinical pathway. Guidelines and source annotations do not automatically determine a patient recommendation."
      },
      "pitfalls": [
        "Fleischner 2017 applies to qualifying incidental nodules in adults 35 or older, excluding screening, immunocompromise and known primary cancer. Do not mix Fleischner, BTS and Lung-RADS thresholds.",
        "Complete typical benign perifissural morphology matters; fissural proximity alone is insufficient. Apparent fat requires a verified intranodular ROI on appropriate source reconstructions.",
        "Negative FDG PET does not reliably exclude malignancy in a pure-ground-glass or low-uptake lesion; morphology, size, actual interval change and clinical context remain necessary.",
        "Persistence, reader malignancy ratings, a dense component and a source binary mask do not establish histology or guaranteed biological behaviour.",
        "DICOM SliceThickness records nominal reconstructed thickness; acquired collimation, true tissue resolution and registration must not be inferred from the voxel grid.",
        "LIDC-IDRI-0525 is one independent source case. Its 33 marks/eight separate released masks and source SR metrics neither autofill the current report nor label every lobe, segment, airway, vessel or diagnostic morphology."
      ],
      "impression_prompts": [
        "Describe every actual nodule with supported site, morphology, total/dense-component measurement and uncertainty.",
        "State genuine comparison findings and reconstruction/method compatibility, or explicitly state that no comparable prior was supplied.",
        "Identify the most suspicious nodule and give an individualized recommendation only after recording eligibility, risk, the exact guideline/version/category and rationale."
